CREATE TABLE t0 (c1); SELECT subq1.c8 FROM (SELECT TRUE AS c8 FROM (SELECT t1.c1 FROM t0 AS t1 LIMIT 5819351589579946652)) AS subq1 WHERE subq1.c8 <> CASE WHEN c8 = CASE WHEN CAST(MAX(TRUE, NULL) AS TEXT) <> c8 OR CASE WHEN NOT c8 IS NULL THEN subq1.c8 END = CASE c8 WHEN subq1.c8 = subq1.c8 THEN subq1.c8 WHEN subq1.c8 = subq1.c8 THEN subq1.c8 ELSE c8 END AND c8 <> c8 THEN c8 END THEN c8 END